import{_ as t,o,c as n,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Two-factor sign-in","description":"","frontmatter":{},"headers":[],"relativePath":"guide/two-factor.md","filePath":"guide/two-factor.md"}'),s={name:"guide/two-factor.md"};function r(a,e,h,l,d,c){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="two-factor-sign-in" tabindex="-1">Two-factor sign-in <a class="header-anchor" href="#two-factor-sign-in" aria-label="Permalink to &quot;Two-factor sign-in&quot;">​</a></h1><p>With two-factor sign-in, signing in to Orbit takes your password and a 6-digit code from an authenticator app on your phone, so a stolen password is not enough on its own. <a href="./api-tokens">API tokens</a> are not affected.</p><h2 id="turning-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-on" aria-label="Permalink to &quot;Turning it on {#turning-on}&quot;">​</a></h2><ol><li>In <strong>Settings → Two-factor sign-in</strong>, select <strong>Turn on</strong>.</li><li>Scan the QR code with an authenticator app (1Password, Google Authenticator, Authy, Bitwarden or any other TOTP app), or type the key under it.</li><li>Type the 6-digit code it shows. Orbit then shows 10 <strong>recovery codes</strong>, only this once. Copy or download them and keep them somewhere safe, such as a password manager.</li></ol><p>From then on, signing in asks for a code after the password.</p><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in {#signing-in}&quot;">​</a></h2><ul><li><strong>Type the current code</strong>, or one of your recovery codes when you do not have your phone. Each recovery code works once; Settings shows how many are left, and <strong>New recovery codes</strong> replaces them all.</li><li><strong>A code works once,</strong> so a code someone saw cannot be used again. Orbit also accepts the code just before and just after the current one, in case the phone&#39;s clock is a little off.</li><li><strong>Wrong codes count</strong> towards the sign-in limit: after five failures, that address waits a minute.</li></ul><h2 id="turning-off" tabindex="-1">Turning it off <a class="header-anchor" href="#turning-off" aria-label="Permalink to &quot;Turning it off {#turning-off}&quot;">​</a></h2><p><strong>Turn off</strong> takes a current code or a recovery code. It is not possible while the administrator requires two-factor sign-in.</p><h2 id="requiring" tabindex="-1">Requiring it for everyone <a class="header-anchor" href="#requiring" aria-label="Permalink to &quot;Requiring it for everyone {#requiring}&quot;">​</a></h2><p>Orbit&#39;s administrator can require it under <strong>Settings → Two-factor sign-in</strong>, once their own is on. Settings shows how many people do not have it yet, and <strong>Settings → Members</strong> marks who does.</p><ul><li><strong>Someone without it</strong> can only set it up, or sign out, until they do: the console takes them to the setup page, and the API answers <code>403 secondFactorSetupRequired</code> to everything else.</li><li><strong>People already signed in</strong> are asked on their next request, not only the next time they sign in.</li><li><strong>API tokens</strong> keep working.</li></ul><h2 id="lost" tabindex="-1">Lost phone and recovery codes <a class="header-anchor" href="#lost" aria-label="Permalink to &quot;Lost phone and recovery codes {#lost}&quot;">​</a></h2><ul><li><p><strong>Orbit&#39;s administrator</strong> selects <strong>Reset 2FA</strong> next to that person in <strong>Settings → Members</strong>. They sign in with their password and, if it is required, set it up again.</p></li><li><p><strong>For the administrator themselves,</strong> or without the console, on the main server:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset-second-factor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ada@example.com</span></span></code></pre></div></li></ul><h2 id="storage" tabindex="-1">How it is stored <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;How it is stored {#storage}&quot;">​</a></h2><p>The secret is sealed with Orbit&#39;s key, like the other secrets, and travels with <code>orbit backup</code>. Recovery codes are kept only as hashes. Codes and secrets are never written to the logs.</p>',16)])])}const p=t(s,[["render",r]]);export{u as __pageData,p as default};
